validate_llm_json <- function(json_text) {
  allowed_types <- c("entity", "named_source", "platform_or_topic", "generic_nonentity", "junk", "mixed_or_needs_review")
  allowed_status <- c("resolved", "unresolved", "not_applicable")
  allowed_subtype <- c("does_not_follow", "cannot_recall", "no_specific_name", "refusal", "unusable", "other_nonresponse")
  obj <- tryCatch(jsonlite::fromJSON(json_text, simplifyVector = FALSE), error = function(e) NULL)
  if (is.null(obj) || !is.list(obj) || is.null(names(obj))) return(list(ok = FALSE, reason = "not_json_object"))
  keys <- c("response_type", "entity_clean", "resolution_status", "nonresponse_subtype", "review_flag", "review_reason")
  if (!setequal(names(obj), keys)) return(list(ok = FALSE, reason = "wrong_fields"))
  if (!is.character(obj$response_type) || length(obj$response_type) != 1L || !obj$response_type %in% allowed_types) return(list(ok = FALSE, reason = "invalid_response_type"))
  if (!is.character(obj$resolution_status) || length(obj$resolution_status) != 1L || !obj$resolution_status %in% allowed_status) return(list(ok = FALSE, reason = "invalid_resolution_status"))
  if (!is.logical(obj$review_flag) || length(obj$review_flag) != 1L || is.na(obj$review_flag)) return(list(ok = FALSE, reason = "invalid_review_flag"))
  if (!is.null(obj$entity_clean) && (!is.character(obj$entity_clean) || length(obj$entity_clean) != 1L || !nzchar(trimws(obj$entity_clean)))) return(list(ok = FALSE, reason = "invalid_entity"))
  if (!is.null(obj$nonresponse_subtype) && (!is.character(obj$nonresponse_subtype) || length(obj$nonresponse_subtype) != 1L || !obj$nonresponse_subtype %in% allowed_subtype)) return(list(ok = FALSE, reason = "invalid_subtype"))
  if (!is.null(obj$review_reason) && (!is.character(obj$review_reason) || length(obj$review_reason) != 1L)) return(list(ok = FALSE, reason = "invalid_review_reason"))
  if (obj$resolution_status == "resolved" && is.null(obj$entity_clean)) return(list(ok = FALSE, reason = "resolved_without_name"))
  if (obj$resolution_status != "resolved" && !is.null(obj$entity_clean)) return(list(ok = FALSE, reason = "name_without_resolved_status"))
  if (!(obj$response_type %in% c("entity", "named_source")) && obj$resolution_status != "not_applicable") return(list(ok = FALSE, reason = "resolution_status_inapplicable"))
  if (obj$response_type != "junk" && !is.null(obj$nonresponse_subtype)) return(list(ok = FALSE, reason = "subtype_nonjunk"))
  if (obj$response_type == "junk" && is.null(obj$nonresponse_subtype)) return(list(ok = FALSE, reason = "missing_junk_subtype"))
  list(ok = TRUE, reason = NA_character_, data = obj)
}
